package com.wms.entity;
import jakarta.persistence.*;import org.hibernate.annotations.CreationTimestamp;import java.time.Instant;
@Entity @Table(name="wms_pending_business_action") public class PendingBusinessAction{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false,length=32)private String businessType;@Column(nullable=false)private Long sourceId;@Column(nullable=false,length=64)private String businessNo;@Lob@Column(nullable=false,columnDefinition="text")private String payload;@Column(nullable=false,length=16)private String status;@Column(nullable=false,length=64)private String createdBy;@CreationTimestamp@Column(updatable=false)private Instant createdAt;private Instant finishedAt;public Long getId(){return id;}public String getBusinessType(){return businessType;}public void setBusinessType(String v){businessType=v;}public Long getSourceId(){return sourceId;}public void setSourceId(Long v){sourceId=v;}public String getBusinessNo(){return businessNo;}public void setBusinessNo(String v){businessNo=v;}public String getPayload(){return payload;}public void setPayload(String v){payload=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public String getCreatedBy(){return createdBy;}public void setCreatedBy(String v){createdBy=v;}public Instant getCreatedAt(){return createdAt;}public Instant getFinishedAt(){return finishedAt;}public void setFinishedAt(Instant v){finishedAt=v;}}
